import { describe, expect, mock, test } from "bun:test"

import { connectIntegrationAndEnableIndexing } from "@/components/onboarding/use-onboarding-integration-connect"

describe("connectIntegrationAndEnableIndexing", () => {
  test("queues plan and reconcile jobs after project connect", async () => {
    const fetchMock = mock(async (input: string) => {
      if (input === "/api/gitlab/integrations/connect") {
        return new Response(
          JSON.stringify({
            data: { id: "integration-1" },
          }),
          { status: 200, headers: { "content-type": "application/json" } },
        )
      }

      if (input === "/api/gitlab/integrations/integration-1/index/enable") {
        return new Response(
          JSON.stringify({
            data: {
              branch: "main",
              job: { id: "plan-job-1" },
              reconcileJob: { id: "reconcile-job-1" },
            },
          }),
          { status: 200, headers: { "content-type": "application/json" } },
        )
      }

      return new Response(JSON.stringify({ error: "Unexpected request" }), {
        status: 500,
        headers: { "content-type": "application/json" },
      })
    })

    const result = await connectIntegrationAndEnableIndexing({
      project: {
        id: "project-1",
        name: "Project 1",
        path: "group/project-1",
        webUrl: "https://gitlab.com/group/project-1",
        defaultBranch: "main",
      },
      normalizedInstance: "https://gitlab.com",
      token: "token-123",
      fetchImpl: fetchMock as unknown as typeof fetch,
    })

    expect(fetchMock).toHaveBeenCalledTimes(2)
    expect(result).toEqual({
      branch: "main",
      planJobId: "plan-job-1",
      reconcileJobId: "reconcile-job-1",
    })

    const firstCall = fetchMock.mock.calls[0]
    expect(firstCall?.[0]).toBe("/api/gitlab/integrations/connect")
    const firstCallInit = firstCall?.[1] as RequestInit
    expect(JSON.parse(String(firstCallInit.body))).toMatchObject({
      instanceUrl: "https://gitlab.com",
      token: "token-123",
      projectId: "project-1",
      projectPath: "group/project-1",
      projectName: "Project 1",
    })

    const secondCall = fetchMock.mock.calls[1]
    expect(secondCall?.[0]).toBe("/api/gitlab/integrations/integration-1/index/enable")
    const secondCallInit = secondCall?.[1] as RequestInit
    expect(JSON.parse(String(secondCallInit.body))).toEqual({
      branch: "main",
    })
  })
})

import { NextResponse } from "next/server"

import { verifyWebhookSecretHash } from "@/lib/gitlab/crypto"
import { getIntegrationById, ingestWebhookDelivery } from "@/lib/gitlab/service"
import { classifyWebhookEvent } from "@/lib/gitlab/webhook"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const readPayload = async (request: Request): Promise<Record<string, unknown> | null> => {
  const parsed = await request.json().catch(() => null)
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    return null
  }

  return parsed as Record<string, unknown>
}

export async function POST(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const { integrationId } = await context.params
  return runWithApiRequestLog({
    request,
    path: `/api/webhooks/gitlab/${integrationId}`,
    event: "api.gitlab.webhook",
    context: {
      integrationId,
    },
    handler: async ({ logger }) => {
      const integration = await getIntegrationById(integrationId)

      if (!integration || integration.status === "disabled") {
        return {
          status: 404,
          outcome: "not_found",
          response: NextResponse.json({ error: "Integration not found." }, { status: 404 }),
        }
      }

      const providedSecret = request.headers.get("x-gitlab-token")
      if (!providedSecret || !integration.webhookSecretHash) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized webhook." }, { status: 401 }),
        }
      }

if (!verifyWebhookSecretHash(providedSecret, integration.webhookSecretHash)) {
  return {
    status: 401,
    outcome: "unauthorized",
    response: NextResponse.json({ error: "Unauthorized webhook." }, { status: 401 }),
  }
}

const eventUuid = request.headers.get("x-gitlab-event-uuid")
if (!eventUuid || !eventUuid.trim()) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Missing X-Gitlab-Event-UUID header." }, { status: 400 }),
  }
}

const eventName = request.headers.get("x-gitlab-event")
if (!eventName || !eventName.trim()) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Missing X-Gitlab-Event header." }, { status: 400 }),
  }
}

const payload = await readPayload(request)
if (!payload) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Invalid webhook payload." }, { status: 400 }),
  }
}

const classified = classifyWebhookEvent(eventName, payload)
const ingestResult = await ingestWebhookDelivery({
  integrationId: integration.id,
  eventUuid: eventUuid.trim(),
  eventName: eventName.trim(),
  eventType: classified.eventType,
  ref: classified.ref,
  payload,
  jobType: classified.jobType,
  normalizedPayload: classified.normalizedPayload,
})

      logger.set({
        webhookEventType: classified.eventType,
        webhookJobType: classified.jobType,
        deduped: ingestResult.deduped,
        enqueued: ingestResult.enqueued,
      })

      return {
        status: 202,
        outcome: "accepted",
        response: NextResponse.json(
          {
            ok: true,
            deduped: ingestResult.deduped,
            enqueued: ingestResult.enqueued,
          },
          { status: 202 },
        ),
      }
    },
  })
}

