import { NextResponse } from "next/server"
import { headers } from "next/headers"
import { auth } from "@/lib/auth"
import { db } from "@/lib/db"
import { onboardingEvents, type OnboardingEventMetadata } from "@/lib/db/schema"
import { recordOnboardingCompletedIfMissing } from "@/lib/onboarding/service"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const ONBOARDING_EVENTS = [
  "onboarding_started",
  "onboarding_token_validated",
  "onboarding_projects_selected",
  "onboarding_completed",
] as const

type OnboardingEvent = (typeof ONBOARDING_EVENTS)[number]

type TrackEventPayload = {
  event: OnboardingEvent
  metadata?: OnboardingEventMetadata
}

const isOnboardingEvent = (value: unknown): value is OnboardingEvent =>
  typeof value === "string" && ONBOARDING_EVENTS.includes(value as OnboardingEvent)

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/onboarding/track",
    event: "api.onboarding.track",
    handler: async ({ logger }) => {
      const headerStorePromise = headers()
      const payloadPromise = request.json().catch(() => null)
      const sessionPromise = headerStorePromise.then((headerStore) =>
        auth.api.getSession({ headers: headerStore }),
      )

      const [session, payloadValue] = await Promise.all([sessionPromise, payloadPromise])

      if (!session?.user?.id) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

const payload = payloadValue as TrackEventPayload | null
if (!payload || !isOnboardingEvent(payload.event)) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Invalid onboarding event." }, { status: 400 }),
  }
}

const metadata =
  payload.metadata && typeof payload.metadata === "object"
    ? payload.metadata
    : undefined

let onboardingDurationMs: number | null = null
let onboardingAlreadyCompleted = false
let onboardingCompletionSource: OnboardingEventMetadata["completionSource"] | null =
  metadata?.completionSource ?? null

if (payload.event === "onboarding_completed") {
  onboardingCompletionSource = metadata?.completionSource ?? "manual"
  const completion = await recordOnboardingCompletedIfMissing({
    userId: session.user.id,
    metadata: {
      ...metadata,
      completionSource: onboardingCompletionSource,
    },
  })
  onboardingDurationMs = completion.onboardingDurationMs
  onboardingAlreadyCompleted = completion.alreadyCompleted
} else {
  await db.insert(onboardingEvents).values({
    userId: session.user.id,
    event: payload.event,
    metadata,
  })
}

logger.set({
  onboardingEvent: payload.event,
  onboardingDurationMs,
  onboardingAlreadyCompleted,
  onboardingCompletionSource,
})

      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          ok: true,
          data: {
            onboardingDurationMs,
            onboardingAlreadyCompleted,
          },
        }),
      }
    },
  })
}

