import { useCallback, useState } from "react"

import {
  getReviewErrorMessage,
  normalizeReviewFindings,
  type DiffReviewPayload,
  type ReviewFinding,
} from "./merge-request-diff-viewer.utils"

export function useMergeRequestAiReview() {
  const [isReviewing, setIsReviewing] = useState(false)
  const [reviewError, setReviewError] = useState("")
  const [reviewSummary, setReviewSummary] = useState("")
  const [reviewFindings, setReviewFindings] = useState<ReviewFinding[]>([])

  const clearReviewFindings = useCallback(() => {
    setReviewFindings([])
    setReviewError("")
    setReviewSummary("")
  }, [])

const runAiReview = useCallback(async (patchText: string) => {
  if (!patchText.trim()) {
    setReviewError("Load a diff before running AI review.")
    setReviewSummary("")
    setReviewFindings([])
    return
  }

  setIsReviewing(true)
  setReviewError("")
  setReviewSummary("")

  try {
    const response = await fetch("/api/review/diff", {
      method: "POST",
      headers: {
        "content-type": "application/json",
      },
      body: JSON.stringify({
        patch: patchText,
      }),
    })

    const payload = (await response.json().catch(() => null)) as DiffReviewPayload | null
    if (!response.ok) {
      throw new Error(getReviewErrorMessage(payload))
    }

    const findings = normalizeReviewFindings(payload?.data?.findings)
    setReviewFindings(findings)

    if (findings.length === 0) {
      setReviewSummary("AI review complete. No findings.")
      return
    }

    const highCount = findings.filter((finding) => finding.severity === "high").length
    const medCount = findings.filter((finding) => finding.severity === "med").length
    const lowCount = findings.length - highCount - medCount
    setReviewSummary(
      `AI review complete: ${findings.length} findings (${highCount} high, ${medCount} med, ${lowCount} low).`,
    )
  } catch (error) {
    setReviewFindings([])
    setReviewSummary("")
    setReviewError(getReviewErrorMessage(error))
  } finally {
    setIsReviewing(false)
  }
}, [])

  return {
    isReviewing,
    reviewError,
    reviewSummary,
    reviewFindings,
    clearReviewFindings,
    runAiReview,
  }
}

