const MAX_PATCH_CHARS = 120_000
const MAX_FINDINGS = 32
const CHAT_TIMEOUT_MS = 35_000
const DEFAULT_AI_API_URL = "https://api.openai.com/v1"
const DEFAULT_AI_MODEL = "gpt-4o-mini"

export type ReviewRequestPayload = {
  patch?: unknown
}

type ResolvedReviewRequest = {
  patch: string
  apiUrl: string
  model: string
  token: string
}

type ReviewFinding = {
  file: string
  line: number
  side: "additions" | "deletions"
  severity: "high" | "med" | "low"
  title: string
  body: string
  confidence: number
}

type ChatCompletionsResponse = {
  choices?: Array<{
    message?: {
      content?: unknown
    }
  }>
}

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

const normalizeApiUrl = (value: string) => value.trim().replace(/\/+$/, "")

export const resolveServerApiUrl = () => {
  const raw = getEnvApiUrl()

  let parsed: URL
  try {
    parsed = new URL(raw)
  } catch {
    throw new Error("AI_API_URL (or OPENAI_BASE_URL) must be a valid absolute URL.")
  }

  if (!/^https?:$/i.test(parsed.protocol)) {
    throw new Error("AI provider URL must use http or https.")
  }
  if (parsed.username || parsed.password) {
    throw new Error("AI provider URL must not include credentials.")
  }

  parsed.hash = ""
  parsed.search = ""
  const pathname = parsed.pathname.replace(/\/+$/, "")
  const normalized = pathname ? `${parsed.origin}${pathname}` : parsed.origin
  return normalizeApiUrl(normalized)
}

const pickFirstNonEmpty = (...values: Array<string | undefined>) => {
  for (const value of values) {
    if (isNonEmptyString(value)) {
      return value.trim()
    }
  }
  return ""
}

const getEnvApiUrl = () =>
  pickFirstNonEmpty(
    process.env.AI_API_URL,
    process.env.OPENAI_BASE_URL,
  ) || DEFAULT_AI_API_URL

const getEnvModel = () =>
  pickFirstNonEmpty(
    process.env.AI_MODEL,
    process.env.OPENAI_MODEL,
  ) || DEFAULT_AI_MODEL

const getEnvToken = () =>
  pickFirstNonEmpty(
    process.env.AI_API_TOKEN,
    process.env.OPENAI_API_KEY,
  )

export const resolveReviewRequestInput = (
  payload: ReviewRequestPayload | null,
): ResolvedReviewRequest => ({
  patch: isNonEmptyString(payload?.patch) ? payload.patch : "",
  apiUrl: resolveServerApiUrl(),
  model: getEnvModel(),
  token: getEnvToken(),
})

const toReviewSide = (value: unknown): ReviewFinding["side"] => {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase()

  if (
    normalized === "deletions" ||
    normalized === "deletion" ||
    normalized === "removed" ||
    normalized === "left"
  ) {
    return "deletions"
  }

  return "additions"
}

const toReviewSeverity = (value: unknown): ReviewFinding["severity"] => {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase()
  if (normalized === "high") {
    return "high"
  }
  if (normalized === "medium" || normalized === "med") {
    return "med"
  }
  return "low"
}

const toConfidence = (value: unknown) => {
  if (typeof value !== "number" || !Number.isFinite(value)) {
    return 0.7
  }

  return Math.max(0, Math.min(1, value))
}

const sanitizeAssistantContent = (content: string) => {
  const trimmed = content.trim()
  const fenced = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/i)
  const candidate = (fenced?.[1] ?? trimmed).trim()
  const firstBrace = candidate.indexOf("{")
  const lastBrace = candidate.lastIndexOf("}")

  if (firstBrace >= 0 && lastBrace > firstBrace) {
    return candidate.slice(firstBrace, lastBrace + 1)
  }

  return candidate
}

const parseFindings = (content: unknown): ReviewFinding[] => {
  if (!isNonEmptyString(content)) {
    return []
  }

  let parsed: unknown
  try {
    parsed = JSON.parse(sanitizeAssistantContent(content))
  } catch {
    return []
  }

  const rawFindings = (() => {
    if (Array.isArray(parsed)) {
      return parsed
    }
    if (parsed && typeof parsed === "object") {
      const maybeFindings = (parsed as { findings?: unknown }).findings
      if (Array.isArray(maybeFindings)) {
        return maybeFindings
      }
    }
    return []
  })()

  const normalized = rawFindings
    .map((value) => {
      if (!value || typeof value !== "object") {
        return null
      }

      const finding = value as Record<string, unknown>
      const line = Number(finding.line)
      const file = String(finding.file ?? "").trim()
      const title = String(finding.title ?? "").trim()
      const body = String(finding.body ?? finding.explanation ?? "").trim()

      if (!file || !title || !body || !Number.isFinite(line) || line < 1) {
        return null
      }

      return {
        file,
        line: Math.floor(line),
        side: toReviewSide(finding.side),
        severity: toReviewSeverity(finding.severity),
        title,
        body,
        confidence: toConfidence(finding.confidence),
      } satisfies ReviewFinding
    })
    .filter((finding): finding is ReviewFinding => finding !== null)

  return normalized.slice(0, MAX_FINDINGS)
}

const getChatCompletionsUrl = (apiUrl: string) => {
  const normalized = normalizeApiUrl(apiUrl)
  if (/\/chat\/completions$/i.test(normalized)) {
    return normalized
  }
  return `${normalized}/chat/completions`
}

const readProviderError = async (response: Response) => {
  const bodyText = await response.text().catch(() => "")
  return bodyText.slice(0, 400)
}

const buildSystemPrompt = () =>
  [
    "You are a senior software code reviewer.",
    "Review a git patch and identify likely real issues only.",
    "Focus on syntax, logic bugs, regressions, null/async issues, and security risks.",
    "Avoid style-only feedback unless it materially affects maintainability or correctness.",
    "Return strictly JSON with shape:",
    '{"findings":[{"file":"path","line":1,"side":"additions|deletions","severity":"high|med|low","title":"short","body":"why it matters + fix hint","confidence":0.0}]}',
    "Use only file paths and changed line numbers from the patch.",
    `Limit findings to ${MAX_FINDINGS}.`,
  ].join("\n")

const requestReview = async ({
  patch,
  apiUrl,
  model,
  token,
}: {
  patch: string
  apiUrl: string
  model: string
  token: string
}) => {
  const controller = new AbortController()
  const timeout = setTimeout(() => {
    controller.abort()
  }, CHAT_TIMEOUT_MS)

  try {
    const response = await fetch(getChatCompletionsUrl(apiUrl), {
      method: "POST",
      headers: {
        "content-type": "application/json",
        authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({
        model,
        temperature: 0.1,
        messages: [
          { role: "system", content: buildSystemPrompt() },
          { role: "user", content: `Review this patch:\n\n${patch}` },
        ],
      }),
      signal: controller.signal,
    })

    if (!response.ok) {
      const providerError = await readProviderError(response)
      throw new Error(
        `AI provider request failed (${response.status})${providerError ? `: ${providerError}` : ""}`,
      )
    }

    const payload = (await response.json()) as ChatCompletionsResponse
    const content = payload.choices?.[0]?.message?.content
    return parseFindings(content)
  } catch (error) {
    if (error instanceof Error && error.name === "AbortError") {
      throw new Error("AI review timed out.")
    }
    throw error
  } finally {
    clearTimeout(timeout)
  }
}

export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/review/diff",
    event: "api.review.diff",
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()

if (!userId) {
  return {
    status: 401,
    outcome: "unauthorized",
    response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
  }
}

const payload = (await request.json().catch(() => null)) as
  | ReviewRequestPayload
  | null

let resolved: ResolvedReviewRequest
try {
  resolved = resolveReviewRequestInput(payload)
} catch (error) {
  const message = error instanceof Error ? error.message : "AI provider URL is invalid."
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: message }, { status: 400 }),
  }
}
const { patch, apiUrl, model, token } = resolved

if (!patch) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Patch is required." }, { status: 400 }),
  }
}
if (!apiUrl || !model || !token) {
  return {
    status: 400,
    outcome: "missing_config",
    response: NextResponse.json(
      { error: "AI token missing. Set AI_API_TOKEN or OPENAI_API_KEY on the server." },
      { status: 400 },
    ),
  }
}

if (patch.length > MAX_PATCH_CHARS) {
  return {
    status: 413,
    outcome: "payload_too_large",
    response: NextResponse.json(
      { error: `Diff too large for AI review. Limit is ${MAX_PATCH_CHARS.toLocaleString()} characters.` },
      { status: 413 },
    ),
  }
}

try {
  const findings = await requestReview({
    patch,
    apiUrl,
    model,
    token,
  })
  let onboardingCompletion: Awaited<
    ReturnType<typeof recordOnboardingCompletedIfMissing>
  > | null = null
  try {
    onboardingCompletion = await recordOnboardingCompletedIfMissing({
      userId,
      metadata: {
        completionSource: "first_ai_review",
        findingsCount: findings.length,
      },
    })
  } catch (completionError) {
    logger.set({
      onboardingCompletionWriteError:
        completionError instanceof Error
          ? completionError.message
          : "unknown",
    })
  }

  logger.set({
    model,
    patchLength: patch.length,
    findingsCount: findings.length,
    onboardingCompleted:
      onboardingCompletion === null
        ? null
        : !onboardingCompletion.alreadyCompleted,
    onboardingAlreadyCompleted: onboardingCompletion?.alreadyCompleted ?? null,
    onboardingDurationMs: onboardingCompletion?.onboardingDurationMs ?? null,
  })

  return {
    status: 200,
    outcome: "success",
    response: NextResponse.json({ data: { findings } }),
  }
} catch (error) {

        const message = error instanceof Error ? error.message : "AI review failed."
        return {
          status: 502,
          outcome: "upstream_error",
          response: NextResponse.json({ error: message }, { status: 502 }),
        }
      }
    },
  })
}

