export function useOnboardingTokenInputs({
  gitlabInstance,
  instanceTokens,
  setGitlabInstance,
  setToken,
  setInstanceTokens,
  setCustomInstance,
  setTokenTestFeedback,
  setWebhookSetupFeedback,
}: UseOnboardingTokenInputsOptions) {
  const resetFeedback = useCallback(() => {
    setTokenTestFeedback(null)
    setWebhookSetupFeedback(null)
  }, [setTokenTestFeedback, setWebhookSetupFeedback])

  const handleInstanceChange = useCallback((instanceKey: string) => {
    if (!isInstanceKey(instanceKey)) {
      return
    }

    setGitlabInstance(instanceKey)
    setToken(instanceTokens[instanceKey] ?? "")
    resetFeedback()
  }, [instanceTokens, resetFeedback, setGitlabInstance, setToken])

  const handleTokenChange = useCallback((nextToken: string) => {
    setToken(nextToken)
    setInstanceTokens((current) => ({
      ...current,
      [gitlabInstance]: nextToken,
    }))
    resetFeedback()
  }, [gitlabInstance, resetFeedback, setInstanceTokens, setToken])

  const handleCustomInstanceChange = useCallback((nextCustomInstance: string) => {
    setCustomInstance(nextCustomInstance)
    resetFeedback()
  }, [resetFeedback, setCustomInstance])

  return {
    handleInstanceChange,
    handleTokenChange,
    handleCustomInstanceChange,
  }
}

