import { useCallback, useRef, type Dispatch, type SetStateAction } from "react"

import { getErrorMessage, resolveGitLabInstance } from "@/components/onboarding/onboarding-flow.utils"
import type { Project, WebhookSetupFeedback } from "@/components/onboarding/onboarding-types"

type UseOnboardingIntegrationConnectOptions = {
  gitlabInstance: string
  customInstance: string
  token: string
  setWebhookSetupFeedback: Dispatch<SetStateAction<WebhookSetupFeedback | null>>
}

type ConnectIntegrationAndEnableIndexingResult = {
  warning?: string
  branch?: string
  planJobId?: string
  reconcileJobId?: string
}

const asRecord = (value: unknown): Record<string, unknown> | null =>
  value && typeof value === "object" ? (value as Record<string, unknown>) : null

const getWarning = (payload: unknown) => {
  const root = asRecord(payload)
  return typeof root?.warning === "string" ? root.warning : ""
}

const getIntegrationId = (payload: unknown) => {
  const root = asRecord(payload)
  const data = asRecord(root?.data)
  return typeof data?.id === "string" && data.id.trim().length > 0 ? data.id : null
}

export const connectIntegrationAndEnableIndexing = async ({
  project,
  normalizedInstance,
  token,
  fetchImpl = fetch,
}: {
  project: Project
  normalizedInstance: string
  token: string
  fetchImpl?: typeof fetch
}): Promise<ConnectIntegrationAndEnableIndexingResult> => {

const response = await fetchImpl("/api/gitlab/integrations/connect", {
  method: "POST",
  headers: {
    "content-type": "application/json",
  },
  body: JSON.stringify({
    instanceUrl: normalizedInstance,
    token,
    projectId: project.id,
    projectPath: project.path,
    projectName: project.name,
  }),
})

const payload = await response.json().catch(() => null)
if (!response.ok) {
  throw new Error(getErrorMessage(payload))
}

const warning = getWarning(payload)
if (warning) {
  return { warning }
}

const integrationId = getIntegrationId(payload)
if (!integrationId) {
  throw new Error("Connect response is missing integration id.")
}

const branch = project.defaultBranch?.trim()
if (!branch) {
  return {
    warning: "Webhook active, but indexing was not queued because no default branch was found.",
  }
}

const enableResponse = await fetchImpl(`/api/gitlab/integrations/${integrationId}/index/enable`, {
  method: "POST",
  headers: {
    "content-type": "application/json",
  },
  body: JSON.stringify({ branch }),
})
const enablePayload = await enableResponse.json().catch(() => null)
if (!enableResponse.ok) {
  throw new Error(getErrorMessage(enablePayload))
}

const enableRoot = asRecord(enablePayload)
const enableData = asRecord(enableRoot?.data)
const job = asRecord(enableData?.job)
const reconcileJob = asRecord(enableData?.reconcileJob)

const resolvedBranch =
  typeof enableData?.branch === "string" && enableData.branch.trim().length > 0
    ? enableData.branch
    : branch

return {
  branch: resolvedBranch,
  planJobId: typeof job?.id === "string" ? job.id : undefined,
  reconcileJobId: typeof reconcileJob?.id === "string" ? reconcileJob.id : undefined,
}

}

export function useOnboardingIntegrationConnect({
  gitlabInstance,
  customInstance,
  token,
  setWebhookSetupFeedback,
}: UseOnboardingIntegrationConnectOptions) {
  const integrationConnectInFlightRef = useRef(new Set<string>())

  const connectIntegration = useCallback(async (project: Project) => {
    const normalizedInstance = resolveGitLabInstance(gitlabInstance, customInstance)
    const connectKey = `${normalizedInstance}::${project.id}`
    if (integrationConnectInFlightRef.current.has(connectKey)) {
      return
    }

    integrationConnectInFlightRef.current.add(connectKey)
    try {
      const result = await connectIntegrationAndEnableIndexing({
        project,
        normalizedInstance,
        token,
      })

      if (result.warning) {
        setWebhookSetupFeedback({
          kind: "warning",
          message: result.warning,
        })
        return
      }

      const jobIdsMessage =
        result.planJobId && result.reconcileJobId
          ? ` Plan job: ${result.planJobId}. Reconcile job: ${result.reconcileJobId}.`
          : ""
      setWebhookSetupFeedback({
        kind: "success",
        message: `Webhook active for ${project.path}. Indexing queued for ${result.branch}.${jobIdsMessage}`,
      })
    } catch (error) {
      setWebhookSetupFeedback({
        kind: "warning",
        message: `Webhook setup warning: ${getErrorMessage(error)}`,
      })
    } finally {
      integrationConnectInFlightRef.current.delete(connectKey)
    }
  }, [customInstance, gitlabInstance, setWebhookSetupFeedback, token])

  return { connectIntegration }
}

