const THEME_MODES: Array<{ value: ThemeMode; label: string }> = [
  { value: "system", label: "System" },
  { value: "light", label: "Light" },
  { value: "dark", label: "Dark" },
  { value: "argus", label: "Argus" },
] as const

const SETTINGS_AUTOSAVE_DEBOUNCE_MS = 100

const isThemeMode = (value: string | null): value is ThemeMode =>
  value === "system" || value === "light" || value === "dark" || value === "argus"

const getActualThemeMode = (mode: ThemeMode) => {
  if (mode === "argus") {
    const prefersDark = typeof window !== "undefined" &&
      window.matchMedia("(prefers-color-scheme: dark)").matches
    return prefersDark ? "argus-dark" : "argus-light"
  }
  return mode
}

const statusLabel: Record<IntegrationStatus, string> = {
  active: "Active",
  degraded: "Degraded",
  disabled: "Disabled",
}

const formatDateTime = (value: string | null) => {
  if (!value) {
    return "Never"
  }

  const parsed = new Date(value)
  if (Number.isNaN(parsed.getTime())) {
    return "Unknown"
  }

  return parsed.toLocaleString()
}

const readAiSettingsFromStorage = (): AISettings => {
  const envDefaults = getEnvAiDefaults()
  if (typeof window === "undefined") {
    return envDefaults
  }

  const aiRaw = window.localStorage.getItem(AI_SETTINGS_STORAGE_KEY)
  if (!aiRaw) {
    return envDefaults
  }

  try {
    const parsed = JSON.parse(aiRaw) as Partial<AISettings>
    return {
      apiUrl:
        typeof parsed.apiUrl === "string" && parsed.apiUrl.trim().length > 0
          ? parsed.apiUrl
          : envDefaults.apiUrl,
      model:
        typeof parsed.model === "string" && parsed.model.trim().length > 0
          ? parsed.model
          : envDefaults.model,
    }
  } catch {
    return envDefaults
  }
}

const readThemeModeFromStorage = (): ThemeMode => {
  if (typeof window === "undefined") {
    return "system"
  }

  const themeRaw = window.localStorage.getItem(THEME_SETTINGS_STORAGE_KEY)
  return isThemeMode(themeRaw) ? themeRaw : "system"
}

export default function SettingsPage() {
  const [activeTab, setActiveTab] = useState("gitlab")
  const [integrations, setIntegrations] = useState<GitLabIntegration[]>([])
  const [integrationBusyId, setIntegrationBusyId] = useState<string | null>(null)
  const [integrationStatus, setIntegrationStatus] = useState("")
  const [aiSettings, setAiSettings] = useState<AISettings>(() => readAiSettingsFromStorage())
  const [aiStatus, setAiStatus] = useState("")
  const [themeMode, setThemeMode] = useState<ThemeMode>(() => readThemeModeFromStorage())
  const [themeStatus, setThemeStatus] = useState("")
  const { setTheme } = useTheme()

const aiAutoSaveTimer = useRef<number | null>(null)
const themeAutoSaveTimer = useRef<number | null>(null)
const hasInitializedAiAutoSave = useRef(false)
const hasInitializedThemeAutoSave = useRef(false)

useEffect(() => {
  setTheme(getActualThemeMode(themeMode))
}, [setTheme, themeMode])

const handleAiSettingChange = (
  key: keyof AISettings,
  value: string,
) => {
  setAiSettings((current) => ({
    ...current,
    [key]: value,
  }))
}

const clearStatusLater = (setStatus: (value: string) => void) => {
  window.setTimeout(() => {
    setStatus("")
  }, 2000)
}

const loadIntegrations = useCallback(async () => {
  const response = await fetch("/api/gitlab/integrations", {
    method: "GET",
    headers: {
      "content-type": "application/json",
    },
  })

  const payload = await response.json().catch(() => null)
  if (!response.ok) {
    const message =
      payload &&
        typeof payload === "object" &&
        "error" in payload &&
        typeof (payload as { error?: unknown }).error === "string"
        ? (payload as { error: string }).error
        : "Failed to load integrations."
    throw new Error(message)
  }

  const data =
    payload &&
      typeof payload === "object" &&
      "data" in payload &&
      Array.isArray((payload as { data?: unknown }).data)
      ? (payload as { data: GitLabIntegration[] }).data
      : []

  setIntegrations(data)
}, [])

const callIntegrationAction = useCallback(async (
  integrationId: string,
  action: "resync" | "disconnect",
  token?: string,
) => {
  const response = await fetch(`/api/gitlab/integrations/${integrationId}/${action}`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify(token ? { token } : {}),
  })

  const payload = await response.json().catch(() => null)
  if (!response.ok) {
    const message =
      payload &&
        typeof payload === "object" &&
        "error" in payload &&
        typeof (payload as { error?: unknown }).error === "string"
        ? (payload as { error: string }).error
        : `Failed to ${action} integration.`
    throw new Error(message)
  }

  return payload
}, [])

const runIntegrationAction = useCallback(async (
  integrationId: string,
  action: "resync" | "disconnect",
  options?: { token?: string },
) => {
  setIntegrationBusyId(integrationId)
  try {
    const payload = await callIntegrationAction(integrationId, action, options?.token)
    const warning =
      payload &&
        typeof payload === "object" &&
        "warning" in payload &&
        typeof (payload as { warning?: unknown }).warning === "string"
        ? (payload as { warning: string }).warning
        : ""

    setIntegrationStatus(
      warning ||
      (action === "resync"
        ? "Integration resync requested."
        : "Integration disconnected."),
    )
    clearStatusLater(setIntegrationStatus)
    await loadIntegrations()
  } catch (error) {
    setIntegrationStatus(error instanceof Error ? error.message : "Action failed.")
    clearStatusLater(setIntegrationStatus)
  } finally {
    setIntegrationBusyId(null)
  }
}, [callIntegrationAction, loadIntegrations])

useEffect(() => {
  void loadIntegrations().catch((error) => {
    setIntegrationStatus(error instanceof Error ? error.message : "Failed to load integrations.")
  })
}, [loadIntegrations])

const clearAISettings = () => {
  setAiSettings(defaultAiSettings)
  setAiStatus("AI settings cleared.")
  clearStatusLater(setAiStatus)
}

const handleResyncIntegration = (integrationId: string) => {
  void runIntegrationAction(integrationId, "resync")
}

const handleRotateToken = (integrationId: string) => {
  const token = window.prompt("Paste replacement GitLab personal access token")
  if (!token || !token.trim()) {
    return
  }
  void runIntegrationAction(integrationId, "resync", { token: token.trim() })
}

const handleDisconnectIntegration = (integrationId: string, projectPath: string) => {
  const confirmed = window.confirm(
    `Unlink ${projectPath} from your account? If this is the last membership, webhook access is disabled.`,
  )
  if (!confirmed) {
    return
  }
  void runIntegrationAction(integrationId, "disconnect")
}

const handleThemeModeChange = (value: ThemeMode) => {
  setThemeMode(value)
}

useEffect(() => {
  if (!hasInitializedAiAutoSave.current) {
    hasInitializedAiAutoSave.current = true
    return
  }
  if (aiAutoSaveTimer.current) {
    window.clearTimeout(aiAutoSaveTimer.current)
    aiAutoSaveTimer.current = null
  }
  aiAutoSaveTimer.current = window.setTimeout(() => {
    if (typeof window !== "undefined") {
      window.localStorage.setItem(AI_SETTINGS_STORAGE_KEY, JSON.stringify(aiSettings))
      setAiStatus("AI settings auto-saved.")
      clearStatusLater(setAiStatus)
    }
    aiAutoSaveTimer.current = null
  }, SETTINGS_AUTOSAVE_DEBOUNCE_MS)

  return () => {
    if (aiAutoSaveTimer.current) {
      window.clearTimeout(aiAutoSaveTimer.current)
      aiAutoSaveTimer.current = null
    }
  }
}, [aiSettings])

useEffect(() => {
  if (!hasInitializedThemeAutoSave.current) {
    hasInitializedThemeAutoSave.current = true
    return
  }
  if (themeAutoSaveTimer.current) {
    window.clearTimeout(themeAutoSaveTimer.current)
    themeAutoSaveTimer.current = null
  }
  themeAutoSaveTimer.current = window.setTimeout(() => {
    if (typeof window !== "undefined") {
      window.localStorage.setItem(THEME_SETTINGS_STORAGE_KEY, themeMode)
      setThemeStatus("Theme preference auto-saved.")
      clearStatusLater(setThemeStatus)
    }
    themeAutoSaveTimer.current = null
  }, SETTINGS_AUTOSAVE_DEBOUNCE_MS)

  return () => {
    if (themeAutoSaveTimer.current) {
      window.clearTimeout(themeAutoSaveTimer.current)
      themeAutoSaveTimer.current = null
    }
  }
}, [themeMode])

useEffect(() => {
  if (themeMode !== "argus") {
    return
  }

  const mediaQuery = window.matchMedia("(prefers-color-scheme: dark)")
  const handleSystemThemeChange = () => {
    setTheme(getActualThemeMode("argus"))
  }
