export async function POST(request: Request) {
  return runWithApiRequestLog({
    request,
    path: "/api/gitlab/integrations/connect",
    event: "api.gitlab.integrations.connect",
    handler: async ({ logger }) => {
      const [userId, payload] = await Promise.all([
        getSessionUserId(),
        request.json().catch(() => null),
      ])

      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const parsed = connectSchema.safeParse(payload)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid connect payload." }, { status: 400 }),
        }
      }

      try {
        const result = await connectGitLabIntegration({
          userId,
          ...parsed.data,
        })
        logger.set({
          integrationId: result.integration.id,
          projectId: parsed.data.projectId,
        })
        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({ data: result.integration, warning: result.warning }),
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : "Failed to connect integration."
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: message }, { status: 400 }),
        }
      }
    },
  })
}

