import type { GitLabCompareChange } from '@/lib/indexing/contracts'

export type DeltaFallbackReason =
  | 'missing_base_sha'
  | 'compare_invalid'
  | 'compare_incomplete'
  | 'too_many_changes'

export type DeltaCompareResult = {
  valid: boolean
  incomplete: boolean
  changes: GitLabCompareChange[]
}

export type DeltaDeleteIntent = {
  path: string
  reason: 'deleted' | 'renamed'
}

export type DeltaUpsertIntent = {
  path: string
  changeType: 'added' | 'modified' | 'renamed'
  oldPath: string | null
}

export const resolveDeltaFallbackReason = (args: {
  baseSha: string | null
  compare: DeltaCompareResult
  maxChanges: number
}): DeltaFallbackReason | null => {
  if (!args.baseSha) {
    return 'missing_base_sha'
  }

  if (!args.compare.valid) {
    return 'compare_invalid'
  }

  if (args.compare.incomplete) {
    return 'compare_incomplete'
  }

  if (args.compare.changes.length > args.maxChanges) {
    return 'too_many_changes'
  }

  return null
}

export const buildDeltaIngestPlan = (
  changes: GitLabCompareChange[],
): {
  deletes: DeltaDeleteIntent[]
  upserts: DeltaUpsertIntent[]
} => {
  const deleteByPath = new Map<string, DeltaDeleteIntent>()
  const upsertByPath = new Map<string, DeltaUpsertIntent>()

  const stageDelete = (path: string, reason: DeltaDeleteIntent['reason']) => {
    if (!path) {
      return
    }

    deleteByPath.set(path, { path, reason })
    upsertByPath.delete(path)
  }

  const stageUpsert = (
    path: string,
    args: {
      changeType: DeltaUpsertIntent['changeType']
      oldPath: string | null
    },
  ) => {
    if (!path) {
      return
    }

    upsertByPath.set(path, {
      path,
      changeType: args.changeType,
      oldPath: args.oldPath,
    })
    deleteByPath.delete(path)
  }

  for (const change of changes) {
    const oldPath = change.oldPath?.trim() || null
    const newPath = change.newPath?.trim() || null

    if (change.type === 'deleted') {
      if (oldPath) {
        stageDelete(oldPath, 'deleted')
      }
      continue
    }

    if (change.type === 'renamed') {
      if (oldPath && newPath && oldPath !== newPath) {
        stageDelete(oldPath, 'renamed')
      }

      if (newPath) {
        stageUpsert(newPath, { changeType: 'renamed', oldPath })
      }
      continue
    }

    if (newPath) {
      stageUpsert(newPath, { changeType: change.type, oldPath })
    }
  }

  return {
    deletes: Array.from(deleteByPath.values()),
    upserts: Array.from(upsertByPath.values()),
  }
}

