import { NextResponse } from "next/server"
import { z } from "zod"

import { getUserIntegration, resyncGitLabIntegration } from "@/lib/gitlab/service"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

const resyncSchema = z.object({
  token: z.string().optional(),
})

export async function POST(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const { integrationId } = await context.params
  return runWithApiRequestLog({
    request,
    path: `/api/gitlab/integrations/${integrationId}/resync`,
    event: "api.gitlab.integrations.resync",
    context: { integrationId },
    handler: async ({ logger }) => {

      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const [integration, payload] = await Promise.all([
        getUserIntegration(integrationId, userId),
        request.json().catch(() => ({})),
      ])

      if (!integration) {
        return {
          status: 404,
          outcome: "not_found",
          response: NextResponse.json({ error: "Integration not found." }, { status: 404 }),
        }
      }

      const parsed = resyncSchema.safeParse(payload)
      if (!parsed.success) {
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: "Invalid resync payload." }, { status: 400 }),
        }
      }

      try {
        const result = await resyncGitLabIntegration({
          integration,
          token: parsed.data.token,
        })
        logger.set({
          hasWarning: Boolean(result.warning),
        })
        return {
          status: 200,
          outcome: "success",
          response: NextResponse.json({ data: result.integration, warning: result.warning }),
        }
      } catch (error) {
        const message = error instanceof Error ? error.message : "Failed to resync integration."
        return {
          status: 400,
          outcome: "invalid_request",
          response: NextResponse.json({ error: message }, { status: 400 }),
        }
      }
    },
  })
}

