import { runIndexingWorkerBatch } from '@/lib/indexing/runner'
import {
  appLog,
  createScopedLogger,
  createCorrelationId,
  flushAppLogger,
  initAppLogger,
  logScopedError,
} from '@/lib/utils/logger'

const parsePositiveInt = (value: string | undefined, fallback: number) => {
  if (!value) {
    return fallback
  }

  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return fallback
  }

  return parsed
}

const parseBoolean = (value: string | undefined): boolean | undefined => {
  if (!value) {
    return undefined
  }

  const normalized = value.trim().toLowerCase()
  if (normalized === '1' || normalized === 'true' || normalized === 'yes') {
    return true
  }
  if (normalized === '0' || normalized === 'false' || normalized === 'no') {
    return false
  }

  return undefined
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))

let shutdownInProgress = false

const flushAndExit = (signal: 'SIGINT' | 'SIGTERM') => {
  if (shutdownInProgress) {
    return
  }
  shutdownInProgress = true

  void (async () => {
    appLog.info({
      event: 'indexer.worker.shutdown_signal',
      signal,
    })
    try {
      await flushAppLogger()
    } finally {
      process.exit(0)
    }
  })()
}

const run = async () => {

initAppLogger({
  service: process.env.INDEXER_SERVICE_NAME?.trim() || 'argus-indexer-worker',
  environment: process.env.INDEXER_ENVIRONMENT?.trim() || process.env.NODE_ENV || 'development',
  version: process.env.INDEXER_SERVICE_VERSION?.trim() || process.env.npm_package_version,
  pretty: parseBoolean(process.env.INDEXER_LOG_PRETTY),
  initEvent: 'indexer.worker.observability_initialized',
})

const batchSize = parsePositiveInt(process.env.INDEXER_BATCH_SIZE, 25)
const pollIntervalMs = parsePositiveInt(process.env.INDEXER_POLL_MS, 30_000)
const continuous = process.env.INDEXER_CONTINUOUS === '1'

process.once('SIGINT', () => flushAndExit('SIGINT'))
process.once('SIGTERM', () => flushAndExit('SIGTERM'))

appLog.info({
  event: 'indexer.worker.started',
  batchSize,
  pollIntervalMs,
  continuous,
})

  do {
    const batchId = createCorrelationId()
    const cycleLog = createScopedLogger({
      method: 'INDEXER',
      path: '/workers/indexer/cycle',
      requestId: batchId,
    })
    const cycleStartedAt = Date.now()
    cycleLog.set({
      event: 'indexer.worker.batch_cycle',
      batchId,
      batchSize,
      continuous,
    })
    let cycleStatus = 500
    try {
      const summary = await runIndexingWorkerBatch(batchSize, { batchId })
      cycleLog.set({
        summary,
      })
      cycleStatus =
        summary.jobsFailed > 0 || summary.jobsDead > 0 || summary.failed > 0
          ? 207
          : 200

      if (!continuous) {
        break
      }

      await sleep(pollIntervalMs)
    } finally {
      cycleLog.emit({
        status: cycleStatus,
        durationMs: Date.now() - cycleStartedAt,
      })
    }
  } while (true)

  await flushAppLogger()
}

run().catch(async (error) => {
  const errorToLog = error instanceof Error ? error : new Error('Indexer worker crashed.')
  const fatalLog = createScopedLogger({
    method: 'INDEXER',
    path: '/workers/indexer',
    requestId: createCorrelationId(),
  })
  fatalLog.set({
    event: 'indexer.worker.fatal',
    outcome: 'crashed',
  })
  logScopedError(fatalLog, errorToLog, {
    code: 'INDEXER_WORKER_FATAL',
    why: 'Unhandled exception escaped the indexer worker loop.',
    fix: 'Inspect preceding batch/job events and dependency health.',
  })
  fatalLog.emit({
    status: 500,
  })

  try {
    await flushAppLogger()
  } finally {
    process.exit(1)
  }
})

import { Buffer } from "node:buffer"
import { GITLAB_DEFAULT_JOB_BATCH_SIZE } from "@/lib/gitlab/constants"

const isLikelyBase64 = (value: string) => /^[A-Za-z0-9+/=_-]+$/.test(value)

const parseEncryptionKey = (value: string) => {
  const trimmed = value.trim()
  if (!trimmed) {
    throw new Error("GITLAB_TOKEN_ENCRYPTION_KEY is required.")
  }

  if (/^[0-9a-fA-F]{64}$/.test(trimmed)) {
    return Buffer.from(trimmed, "hex")
  }

  if (isLikelyBase64(trimmed)) {
    const normalized = trimmed.replace(/-/g, "+").replace(/_/g, "/")
    try {
      const decoded = Buffer.from(normalized, "base64")
      if (decoded.length === 32) {
        return decoded
      }
    } catch {
    }
  }

  const utf8 = Buffer.from(trimmed, "utf8")
  if (utf8.length === 32) {
    return utf8
  }

  throw new Error(
    "GITLAB_TOKEN_ENCRYPTION_KEY must decode to exactly 32 bytes (raw/base64/base64url/hex).",
  )
}

const normalizePublicUrl = (value: string) => {
  const trimmed = value.trim()
  if (!trimmed) {
    throw new Error("BETTER_AUTH_URL is required.")
  }

  let parsed: URL
  try {
    parsed = new URL(trimmed)
  } catch {
    throw new Error("BETTER_AUTH_URL must be a valid absolute URL.")
  }

  if (!/^https?:$/i.test(parsed.protocol)) {
    throw new Error("BETTER_AUTH_URL must use http or https.")
  }

  parsed.hash = ""
  parsed.search = ""
  const pathname = parsed.pathname.replace(/\/+$/, "")
  return pathname ? `${parsed.origin}${pathname}` : parsed.origin
}

const parseBatchSize = (value: string | undefined) => {
  if (!value) {
    return GITLAB_DEFAULT_JOB_BATCH_SIZE
  }

  const parsed = Number.parseInt(value, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) {
    throw new Error("GITLAB_JOB_BATCH_SIZE must be a positive integer when set.")
  }

  return Math.min(parsed, 200)
}

const readNonEmpty = (name: string, value: string | undefined) => {
  if (!value || !value.trim()) {
    throw new Error(`${name} is required.`)
  }
  return value.trim()
}

const appPublicUrl = normalizePublicUrl(readNonEmpty("BETTER_AUTH_URL", process.env.BETTER_AUTH_URL))
const tokenEncryptionKey = parseEncryptionKey(
  readNonEmpty("GITLAB_TOKEN_ENCRYPTION_KEY", process.env.GITLAB_TOKEN_ENCRYPTION_KEY),
)
const internalRunnerKey = readNonEmpty("INTERNAL_RUNNER_KEY", process.env.INTERNAL_RUNNER_KEY)
const jobBatchSize = parseBatchSize(process.env.GITLAB_JOB_BATCH_SIZE)

export const gitlabEnv = {
  appPublicUrl,
  internalRunnerKey,
  jobBatchSize,
  tokenEncryptionKey,
} as const

import type { DiffLineAnnotation, FileDiffMetadata } from "@pierre/diffs"
import { useMemo } from "react"

import {
  findHunkIndexForFinding,
  getStableFileKey,
  normalizePatchPath,
  type ReviewAnnotationMetadata,
  type ReviewCoverage,
  type ReviewFinding,
} from "./merge-request-diff-viewer.utils"

type UseMergeRequestReviewMappingOptions = {
  parsedFiles: FileDiffMetadata[]
  reviewFindings: ReviewFinding[]
}

export function useMergeRequestReviewMapping({
  parsedFiles,
  reviewFindings,
}: UseMergeRequestReviewMappingOptions) {
  const parsedFileLookup = useMemo(() => {
    const lookup = new Map<string, FileDiffMetadata>()
    for (const file of parsedFiles) {
      const candidates = [file.name, file.prevName].filter(
        (candidate): candidate is string => typeof candidate === "string" && candidate.length > 0,
      )

      for (const candidate of candidates) {
        const normalized = normalizePatchPath(candidate)
        if (!lookup.has(normalized)) {
          lookup.set(normalized, file)
        }
      }
    }
    return lookup
  }, [parsedFiles])

const reviewAnnotationsByFileKey = useMemo<
  Record<string, DiffLineAnnotation<ReviewAnnotationMetadata>[]>
>(() => {
  const next: Record<string, DiffLineAnnotation<ReviewAnnotationMetadata>[]> = {}

  for (const finding of reviewFindings) {
    const targetFile = parsedFileLookup.get(normalizePatchPath(finding.file))
    if (!targetFile) {
      continue
    }

    const key = getStableFileKey(targetFile)
    const annotations = next[key] ?? []
    annotations.push({
      side: finding.side,
      lineNumber: finding.line,
      metadata: {
        severity: finding.severity,
        title: finding.title,
        body: finding.body,
        confidence: finding.confidence,
      },
    })
    next[key] = annotations
  }

  for (const annotations of Object.values(next)) {
    annotations.sort((a, b) => a.lineNumber - b.lineNumber)
  }

  return next
}, [parsedFileLookup, reviewFindings])

  const reviewCoverageByFileKey = useMemo<Record<string, ReviewCoverage>>(() => {
    const next: Record<string, { findingCount: number; hunkSet: Set<number> }> = {}

    for (const finding of reviewFindings) {
      const targetFile = parsedFileLookup.get(normalizePatchPath(finding.file))
      if (!targetFile) {
        continue
      }

      const fileKey = getStableFileKey(targetFile)
      const current = next[fileKey] ?? { findingCount: 0, hunkSet: new Set<number>() }
      current.findingCount += 1
      const hunkIndex = findHunkIndexForFinding(targetFile, finding)
      if (hunkIndex >= 0) {
        current.hunkSet.add(hunkIndex + 1)
      }
      next[fileKey] = current
    }

    const finalized: Record<string, ReviewCoverage> = {}
    for (const [fileKey, value] of Object.entries(next)) {
      finalized[fileKey] = {
        findingCount: value.findingCount,
        hunkIndices: Array.from(value.hunkSet).sort((a, b) => a - b),
      }
    }

    return finalized
  }, [parsedFileLookup, reviewFindings])

  return {
    reviewAnnotationsByFileKey,
    reviewCoverageByFileKey,
  }
}

