export const getInstanceByKey = (instance: string) =>
  INSTANCE_PRESETS.find((item) => item.key === instance) ?? INSTANCE_PRESETS[0]

export const isInstanceKey = (instance: string): instance is GitLabInstancePreset["key"] =>
  INSTANCE_PRESETS.some((item) => item.key === instance)

export const resolveGitLabInstance = (instance: string, customValue: string) => {
  const selectedInstance = getInstanceByKey(instance)
  const value =
    (selectedInstance.isCustom ? customValue : selectedInstance.defaultUrl).trim()
  if (!value) {
    throw new Error("Please select or enter a GitLab instance.")
  }
  return value.replace(/\/+$/, "")
}

export const buildEmptyInstanceTokens = () => {
  const values: Record<string, string> = {}
  for (const instance of INSTANCE_PRESETS) {
    values[instance.key] = ""
  }
  return values
}

export const isStringRecord = (value: unknown): value is Record<string, string> =>
  Boolean(value) &&
  typeof value === "object" &&
  !Array.isArray(value) &&
  Object.values(value as Record<string, unknown>).every((item) => typeof item === "string")

export const readPersistedState = (): Partial<OnboardingSessionState> => {
  const raw = window.sessionStorage.getItem(ONBOARDING_STORAGE_KEY)
  if (!raw) {
    return {}
  }

  try {
    const parsed = JSON.parse(raw) as Partial<OnboardingSessionState>
    return parsed && typeof parsed === "object" ? parsed : {}
  } catch {
    return {}
  }
}

export const isNonEmptyString = (value: unknown): value is string =>
  typeof value === "string" && value.trim().length > 0

export const hashTokenForCache = (value: string) => {
  let hash = 0x811c9dc5
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index)
    hash = Math.imul(hash, 0x01000193)
  }
  return (hash >>> 0).toString(16).padStart(8, "0")
}

export const getErrorMessage = (value: unknown) => {
  if (typeof value === "string") {
    return value
  }
  if (value instanceof Error) {
    return value.message
  }
  if (value && typeof value === "object" && "error" in value) {
    return String((value as { error?: string }).error)
  }
  return "Something went wrong."
}

export type TokenTestResultCache = Map<
  string,
  { checkedAt: number; feedback: TokenTestFeedback }
>

export const loadTokenTestCache = () => {
  const raw = window.sessionStorage.getItem(ONBOARDING_TOKEN_TEST_CACHE_KEY)
  if (!raw) {
    return new Map<string, { checkedAt: number; feedback: TokenTestFeedback }>()
  }

  try {
    const parsed = JSON.parse(raw) as Record<
      string,
      { checkedAt: number; feedback: TokenTestFeedback } | undefined
    >
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return new Map()
    }

    const entries = Object.entries(parsed).filter(([, item]) => {
      if (!item || typeof item !== "object") {
        return false
      }
      if (typeof item.checkedAt !== "number" || !Number.isFinite(item.checkedAt)) {
        return false
      }
      if (!item.feedback || typeof item.feedback !== "object") {
        return false
      }
      if (
        item.feedback.kind !== "success" &&
        item.feedback.kind !== "error"
      ) {
        return false
      }
      if (typeof item.feedback.message !== "string") {
        return false
      }
      return true
    })

    return new Map(entries)
  } catch {
    return new Map()
  }
}

export const pruneTokenTestCache = (cache: TokenTestResultCache, now: number) => {
  for (const [signature, entry] of cache) {
    if (now - entry.checkedAt >= TOKEN_TEST_CACHE_TTL_MS) {
      cache.delete(signature)
    }
  }
}

export const persistTokenTestCache = (cache: TokenTestResultCache) => {
  try {
    const now = Date.now()
    pruneTokenTestCache(cache, now)
    const payload = Object.fromEntries(cache.entries())
    window.sessionStorage.setItem(ONBOARDING_TOKEN_TEST_CACHE_KEY, JSON.stringify(payload))
  } catch {
    // best-effort
  }
}

import { useMemo } from "react"

import {
  getInstanceByKey,
  hashTokenForCache,
  RECENT_PROJECTS_LIMIT,
  resolveGitLabInstance,
} from "@/components/onboarding/onboarding-flow.utils"
import type { MergeRequest, Project } from "@/components/onboarding/onboarding-types"

type UseOnboardingDerivedStateOptions = {
  token: string
  gitlabInstance: string
  customInstance: string
  projects: Project[]
  selectedProjectId: string
  mergeRequests: MergeRequest[]
  selectedMergeRequestId: string
  projectSearchQuery: string
}

export function useOnboardingDerivedState({
  token,
  gitlabInstance,
  customInstance,
  projects,
  selectedProjectId,
  mergeRequests,
  selectedMergeRequestId,
  projectSearchQuery,
}: UseOnboardingDerivedStateOptions) {
  const selectedProject = projects.find((project) => project.id === selectedProjectId)
  const selectedMergeRequest = mergeRequests.find((mr) => mr.id === selectedMergeRequestId)

  const canLoadProjects = useMemo(
    () =>
      token.trim().length > 0 &&
      (getInstanceByKey(gitlabInstance).isCustom
        ? customInstance.trim().length > 0
        : getInstanceByKey(gitlabInstance).defaultUrl.trim().length > 0),
    [token, gitlabInstance, customInstance],
  )

  const normalizedProjectSearchQuery = useMemo(
    () => projectSearchQuery.trim().toLowerCase(),
    [projectSearchQuery],
  )

  const filteredProjects = useMemo(() => {
    if (!normalizedProjectSearchQuery) {
      return projects
    }

    return projects.filter((project) => {
      const name = project.name.toLowerCase()
      const path = project.path.toLowerCase()
      return (
        name.includes(normalizedProjectSearchQuery) ||
        path.includes(normalizedProjectSearchQuery)
      )
    })
  }, [projects, normalizedProjectSearchQuery])

  const recentProjects = useMemo(
    () => filteredProjects.slice(0, RECENT_PROJECTS_LIMIT),
    [filteredProjects],
  )

  const resolvedGitLabInstance = useMemo(() => {
    if (!token.trim()) {
      return ""
    }

    try {
      return resolveGitLabInstance(gitlabInstance, customInstance)
    } catch {
      return ""
    }
  }, [token, gitlabInstance, customInstance])

  const tokenCacheHash = useMemo(() => {
    const trimmed = token.trim()
    if (!trimmed) {
      return ""
    }
    return hashTokenForCache(trimmed)
  }, [token])

  const projectsCacheKey = useMemo(() => {
    if (!tokenCacheHash) {
      return ""
    }

    try {
      const normalizedInstance = resolveGitLabInstance(gitlabInstance, customInstance)
      return `${normalizedInstance}::${tokenCacheHash}`
    } catch {
      return ""
    }
  }, [tokenCacheHash, gitlabInstance, customInstance])

  return {
    selectedProject,
    selectedMergeRequest,
    canLoadProjects,
    normalizedProjectSearchQuery,
    recentProjects,
    resolvedGitLabInstance,
    tokenCacheHash,
    projectsCacheKey,
  }
}

import { defineConfig } from "drizzle-kit";

const command = process.argv[2];
const databaseUrl = process.env.DATABASE_URL;

if (!databaseUrl && command !== "generate") {
  throw new Error(
    `DATABASE_URL is required for drizzle-kit ${command ?? "command"}. Add it to your environment or .env.`,
  );
}

export default defineConfig({
  out: "./drizzle",
  schema: "./src/lib/db/schema/**/*.ts",
  dialect: "postgresql",
  dbCredentials: {
    url: databaseUrl ?? "postgresql://postgres:postgres@localhost:5432/postgres",
  },
});

const claimPlannedRuns = async (batchSize: number): Promise<ClaimedRun[]> => {
  const query = sql<ClaimedRun>`
    with due_runs as (
      select ${indexRuns.id}
      from ${indexRuns}
      where ${indexRuns.status} = 'planned'
      order by ${indexRuns.createdAt} asc
      for update skip locked
      limit ${batchSize}
    )
    update ${indexRuns}
      set
        ${indexRuns.status} = 'ingesting',
        ${indexRuns.updatedAt} = now()
    from due_runs
    where ${indexRuns.id} = due_runs.id
    returning ${indexRuns.id} as "id"
  `

  const result = await db.execute(query)
  return result.rows.map((row) => ({ id: String((row as { id: unknown }).id) }))
}

export const runIndexingWorkerBatch = async (
  batchSize = 10,
  options: RunIndexingWorkerBatchOptions = {},
) => {
  const startedAt = Date.now()
  const normalizedBatchSize = Math.max(1, Math.min(200, Math.floor(batchSize)))
  const batchLog = createScopedLogger({
    method: 'INDEXER',
    path: '/workers/indexer/batch',
    requestId: options.batchId,
  })
  batchLog.set({
    event: 'indexer.batch.processing',
    batchId: options.batchId ?? null,
    batchSize: normalizedBatchSize,
  })
  const summary: IndexingWorkerBatchSummary = {
    jobsClaimed: 0,
    jobsSucceeded: 0,
    jobsFailed: 0,
    jobsDead: 0,
    planJobs: 0,
    reconcileJobs: 0,
    reconcileScheduled: 0,
    artifactCleanupTriggered: false,
    artifactCleanupDeletedRuns: 0,
    artifactCleanupDeletedBytes: 0,
    artifactCleanupErrors: 0,
    claimed: 0,
    ready: 0,
    failed: 0,
    superseded: 0,
    skipped: 0,
  }

let batchStatus = 200

try {
  const nowMs = Date.now()
  if (nowMs - lastArtifactCleanupAt >= resolveArtifactCleanupIntervalMs()) {
    try {
      const cleanupSummary = await cleanupIndexArtifacts()
      summary.artifactCleanupTriggered = cleanupSummary.lock === 'acquired'
      summary.artifactCleanupDeletedRuns = cleanupSummary.deletedRuns
      summary.artifactCleanupDeletedBytes = cleanupSummary.deletedBytes
      summary.artifactCleanupErrors = cleanupSummary.errors
      if (cleanupSummary.lock === 'acquired') {
        lastArtifactCleanupAt = nowMs
      }
      batchLog.set({
        artifactCleanup: cleanupSummary,
      })
    } catch (error) {
      const errorToLog =
        error instanceof Error
          ? error
          : new Error('Unexpected artifact cleanup processing error.')
      logScopedError(batchLog, errorToLog, {
        code: 'INDEXER_ARTIFACT_CLEANUP_FAILED',
        why: 'Failed to prune stale indexing artifacts.',
        fix: 'Inspect artifact retention policy and artifact store connectivity.',
      })
    }
  }

try {
  summary.reconcileScheduled = await enqueueDueReconcileJobs()
  batchLog.set({
    reconcileScheduled: summary.reconcileScheduled,
  })
} catch (error) {
  const errorToLog =
    error instanceof Error
      ? error
      : new Error('Unexpected reconcile scheduler processing error.')
  logScopedError(batchLog, errorToLog, {
    code: 'INDEXER_RECONCILE_SCHEDULE_FAILED',
    why: 'Failed to enqueue due reconcile jobs.',
    fix: 'Inspect reconcile scheduler query and index_jobs/index_branch_states health.',
  })
}

const claimedJobs = await claimDueIndexJobs(normalizedBatchSize)
summary.jobsClaimed = claimedJobs.length
batchLog.set({
  jobsClaimed: claimedJobs.length,
})

for (const job of claimedJobs) {
  const jobLog = createScopedLogger({
    method: 'INDEX_JOB',
    path: `/workers/indexer/jobs/${job.jobType}`,
    requestId: job.id,
  })
  const jobStartedAt = Date.now()
  jobLog.set({
    event: 'indexer.job.processing',
    batchId: options.batchId ?? null,
    jobId: job.id,
    jobType: job.jobType,
    integrationId: job.integrationId,
    branch: job.branch,
    configHash: job.configHash,
    attempts: job.attempts,
    debounceKey: job.debounceKey,
  })

  let jobStatus = 500

try {
  const result =
    job.jobType === 'plan'
      ? await (async () => {
          if (!job.branch) {
            throw new Error('Plan job is missing branch.')
          }

          const plannedRun = await processPlanJob({
            integrationId: job.integrationId,
            branch: job.branch,
            hintedHeadSha: job.hintedHeadSha ?? undefined,
            configHash: job.configHash ?? undefined,
            configJson: job.configJson ?? undefined,
            forceReplan: isForcedPlanDebounceKey(job.debounceKey),
          })

          return {
            type: 'plan' as const,
            payload: { run: plannedRun },
          }
        })()
      : await (async () => {
          const reconcile = await processReconcileJob({
            integrationId: job.integrationId,
          })
          return {
            type: 'reconcile' as const,
            payload: reconcile,
          }
        })()

  const committed = await markIndexJobSucceeded({
    jobId: job.id,
    result:
      result.type === 'plan'
        ? {
            type: 'plan',
            ...result.payload,
          }
        : {
            type: 'reconcile',
            ...result.payload,
          },
  })

if (committed) {
  summary.jobsSucceeded += 1
  if (job.jobType === 'plan') {
    summary.planJobs += 1
  } else {
    summary.reconcileJobs += 1
  }

  jobLog.set({
    outcome: 'succeeded',
    committed,
    resultType: result.type,
    runId: result.type === 'plan' ? result.payload.run.runId : null,
    runMode: result.type === 'plan' ? result.payload.run.mode : null,
    reconcileChecked: result.type === 'reconcile' ? result.payload.checked : null,
    reconcileEnqueued: result.type === 'reconcile' ? result.payload.enqueued : null,
  })
  jobStatus = 200
} else {
  jobLog.set({
    outcome: 'succeeded_not_committed',
    committed,
  })
  jobStatus = 409
}

  } catch (error) {
    const status = await markIndexJobFailed({
      job,
      error,
    })
    if (status === 'dead') {
      summary.jobsDead += 1
      jobStatus = 410
    } else if (status === 'failed') {
      summary.jobsFailed += 1
      jobStatus = 500
    } else {
      jobStatus = 500
    }

    const errorToLog =
      error instanceof Error ? error : new Error('Unexpected indexing job processing error.')
    logScopedError(jobLog, errorToLog, {
      code: 'INDEX_JOB_FAILED',
      why: status ? `Job moved to ${status}.` : 'Job failure status was not persisted.',
      fix: 'Inspect job payload and processor path for deterministic retries.',
      details: {
        outcome: 'failed',
        failureStatus: status ?? 'unknown',
      },
    })
  } finally {
    jobLog.emit({
      status: jobStatus,
      durationMs: Date.now() - jobStartedAt,
    })
  }
}

const claimedRuns = await claimPlannedRuns(normalizedBatchSize)
summary.claimed = claimedRuns.length
batchLog.set({
  runsClaimed: claimedRuns.length,
})

for (const run of claimedRuns) {

  const runLog = createScopedLogger({
    method: 'INGEST',
    path: '/workers/indexer/runs/ingest',
    requestId: run.id,
  })
  const runStartedAt = Date.now()
  runLog.set({
    event: 'indexer.run.processing',
    batchId: options.batchId ?? null,
    runId: run.id,
  })

  let runStatus = 500
  try {
    const result = await processIngestJob({ runId: run.id })

    if (result.status === 'ready') {
      summary.ready += 1
    } else if (result.status === 'failed') {
      summary.failed += 1
    } else if (result.status === 'superseded') {
      summary.superseded += 1
    } else {
      summary.skipped += 1
    }

    runLog.set({
      outcome: result.status,
    })
    runStatus =
      result.status === 'ready'
        ? 200
        : result.status === 'failed'
          ? 500
          : result.status === 'superseded'
            ? 409
            : 204
  } catch (error) {
    const errorToLog =
      error instanceof Error ? error : new Error('Unexpected ingest run processing error.')
    logScopedError(runLog, errorToLog, {
      code: 'INGEST_RUN_FAILED',
      why: 'Ingest processor threw before finalize.',
      fix: 'Inspect ingest worker dependencies and run context for this run id.',
    })
    runStatus = 500
    throw error
  } finally {
    runLog.emit({
      status: runStatus,
      durationMs: Date.now() - runStartedAt,
    })
  }
}

    const hasFailures = summary.jobsFailed > 0 || summary.jobsDead > 0 || summary.failed > 0
    batchLog.set({
      outcome: hasFailures ? 'partial_failure' : 'success',
    })
    if (hasFailures) {
      batchStatus = 207
    }

    return summary
  } finally {
    const durationMs = Date.now() - startedAt
    batchLog.set({
      durationMs,
      summary,
    })
    batchLog.emit({
      status: batchStatus,
      durationMs,
    })
  }
}

