import { copyFile, mkdir, readdir } from 'node:fs/promises'
import path from 'node:path'

const DEFAULT_REPORTS_DIR = path.join(process.cwd(), '.benchmarks', 'indexing')
const DEFAULT_BASELINE_PATH = path.join(DEFAULT_REPORTS_DIR, 'phase2-baseline.json')

const getArgValue = (flag: string): string | null => {
  const args = process.argv.slice(2)
  const index = args.indexOf(flag)
  if (index < 0) {
    return null
  }

  const next = args[index + 1]
  if (!next || next.startsWith('--')) {
    return null
  }

  return next
}

const listReportFiles = async (reportsDir: string): Promise<string[]> => {
  const entries = await readdir(reportsDir, { withFileTypes: true })
  return entries
    .filter((entry) => entry.isFile())
    .map((entry) => entry.name)
    .filter((name) => /^phase2-.*\.json$/.test(name) && name !== 'phase2-baseline.json')
    .sort()
}

const resolveLatestReportPath = async (reportsDir: string): Promise<string> => {
  const reportFiles = await listReportFiles(reportsDir)
  const latest = reportFiles[reportFiles.length - 1]
  if (!latest) {
    throw new Error(`No benchmark reports found in ${reportsDir}. Run bench:indexing:phase2 first.`)
  }

  return path.join(reportsDir, latest)
}

const main = async () => {
  const reportsDir = process.env.INDEXING_BENCH_REPORTS_DIR?.trim() || DEFAULT_REPORTS_DIR
  const baselinePath = process.env.INDEXING_BENCH_BASELINE_PATH?.trim() || DEFAULT_BASELINE_PATH
  const explicitSource = getArgValue('--source')

  await mkdir(path.dirname(baselinePath), { recursive: true })

  const sourcePath = explicitSource
    ? path.resolve(explicitSource)
    : await resolveLatestReportPath(reportsDir)

  await copyFile(sourcePath, baselinePath)
  console.log(`Baseline updated: ${baselinePath}`)
  console.log(`Source report: ${sourcePath}`)
}

main().catch((error) => {
  console.error('[indexing-benchmark:set-baseline] failed', error)
  process.exit(1)
})

"use client"

import type { FileDiffMetadata } from "@pierre/diffs"
import { useCallback } from "react"

import { buildMergeRequestDiffPanelProps } from "./build-merge-request-diff-panel-props"
import type { MergeRequestDiffPanelProps } from "./merge-request-diff-panel"
import { useMergeRequestDiffModel } from "./use-merge-request-diff-model"
import {
  FILE_BATCH_SIZE,
  getStableFileKey,
  type MergeRequestDiffViewerProps,
} from "./merge-request-diff-viewer.utils"

export function useMergeRequestDiffViewerController({
  instanceUrl,
  token,
  projectId,
  mergeRequestIid,
}: MergeRequestDiffViewerProps): MergeRequestDiffPanelProps {
  const model = useMergeRequestDiffModel({
    instanceUrl,
    token,
    projectId,
    mergeRequestIid,
  })

  const getFileKey = useCallback((file: FileDiffMetadata) => {
    return getStableFileKey(file)
  }, [])
  const { setCollapsedFileKeys } = model.ui

  const toggleFileCollapsed = useCallback(
    (file: FileDiffMetadata) => {
      const key = getFileKey(file)
      setCollapsedFileKeys((current) => {
        const next = new Set(current)
        if (next.has(key)) {
          next.delete(key)
        } else {
          next.add(key)
        }
        return next
      })
    },
    [getFileKey, setCollapsedFileKeys],
  )

  return buildMergeRequestDiffPanelProps({
    filteredFiles: model.derived.filteredFiles,
    totals: model.derived.totals,
    reviewFindingsCount: model.ai.reviewFindings.length,
    filenameFilter: model.ui.filenameFilter,
    isDiffLoading: model.isDiffLoading,
    isReviewing: model.ai.isReviewing,

    remainingFileCount: model.derived.filteredFiles.length - model.derived.visibleFileCount,
    nextVisibleFileCount: Math.min(
      model.derived.visibleFileCount + FILE_BATCH_SIZE,
      model.derived.filteredFiles.length,
    ),
  })
}

