import { NextResponse } from "next/server"
import { z } from "zod"

import { getUserIntegration } from "@/lib/gitlab/service"
import { enqueuePlanJob } from "@/lib/indexing/job-queue"
import { getSessionUserId } from "@/lib/session"
import { logScopedError, runWithApiRequestLog } from "@/lib/utils/logger"

const CONFIG_HASH_PATTERN = /^[A-Za-z0-9._-]{1,120}$/

const reindexSchema = z.object({
  branch: z
    .string()
    .trim()
    .min(1)
    .max(255)
    .refine((value) => !/[\0\r\n\\]/.test(value), "Invalid branch name."),
  configHash: z
    .string()
    .trim()
    .regex(CONFIG_HASH_PATTERN, "Invalid config hash.")
    .optional(),
})

export async function POST(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const { integrationId } = await context.params

  return runWithApiRequestLog({
    request,
    path: `/api/gitlab/integrations/${integrationId}/index/reindex`,
    event: "api.gitlab.index.reindex",
    context: { integrationId },
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const [integration, payload] = await Promise.all([
        getUserIntegration(integrationId, userId),
        request.json().catch(() => ({})),
      ])

if (!integration) {
  return {
    status: 404,
    outcome: "not_found",
    response: NextResponse.json({ error: "Integration not found." }, { status: 404 }),
  }
}

if (integration.status === "disabled") {
  return {
    status: 409,
    outcome: "conflict",
    response: NextResponse.json({ error: "Integration is disabled." }, { status: 409 }),
  }
}

const parsed = reindexSchema.safeParse(payload)
if (!parsed.success) {
  return {
    status: 400,
    outcome: "invalid_request",
    response: NextResponse.json({ error: "Invalid reindex payload." }, { status: 400 }),
  }
}

try {
  const queuedJob = await enqueuePlanJob({
    integrationId: integration.id,
    branch: parsed.data.branch,
    configHash: parsed.data.configHash,
    forceReplan: true,
  })

  logger.set({
    branch: parsed.data.branch,
    configHash: parsed.data.configHash ?? null,
    planJobId: queuedJob.id,
    forced: true,
  })

  return {
    status: 202,
    outcome: "accepted",
    response: NextResponse.json({
      data: {
        integrationId: integration.id,
        branch: parsed.data.branch,
        job: queuedJob,
        runId: null,
        expectedTransition: {
          jobStatus: {
            from: queuedJob.status,
            to: "processing",
          },
          runStatus: {
            from: "planned",
            to: "ready",
            intermediate: ["ingesting", "indexing"],
          },
        },
      },
    }, { status: 202 }),
  }
} catch (error) {

        logScopedError(logger, error, {
          code: "INDEX_REINDEX_ENQUEUE_FAILED",
          why: "Failed to persist forced plan job for manual branch repair.",
          fix: "Inspect indexing queue DB health and retry reindex request.",
          details: {
            integrationId: integration.id,
            branch: parsed.data.branch,
          },
        })
        return {
          status: 500,
          outcome: "error",
          response: NextResponse.json({ error: "Failed to enqueue reindex job." }, { status: 500 }),
        }
      }
    },
  })
}

import { readFileSync } from "node:fs";
import { isAbsolute, join, relative } from "node:path";
import { globSync } from "node:fs";

const repoRoot = process.cwd();
const srcRoot = join(repoRoot, "src");
const loggerFile = join(srcRoot, "lib", "utils", "logger.ts");

const read = (path) => readFileSync(path, "utf8");
const toAbsolutePath = (path) => (isAbsolute(path) ? path : join(repoRoot, path));
const toRepoRelativePath = (path) => relative(repoRoot, path);
const sensitiveLogKeyRegex =
  /\b(token|password|secret|authorization|cookie|sessionToken|sessionId|apiKey|privateKey|accessKey)\b\s*:/i;

const loggingObjectLiteralRegexes = [
  /(logger\.(set|emit)|appLog\.(info|warn|error|debug))\s*\(\s*\{([\s\S]{0,700}?)\}\s*\)/g,
  /logScopedError\([\s\S]{0,200}?,\s*[\s\S]{0,200}?,\s*\{([\s\S]{0,700}?)\}\s*\)/g,
];

const fail = (label, items) => {
  if (items.length === 0) {
    return;
  }

  console.error(`\n[observability] ${label}`);
  for (const item of items) {
    console.error(`- ${item}`);
  }
};

const findDirectEvlogImports = () => {
  const files = globSync("src/**/*.{ts,tsx,mts,cts}", {
    cwd: repoRoot,
    absolute: true,
  });
  const violations = [];

  for (const file of files) {
    const absolutePath = toAbsolutePath(file);
    if (absolutePath === loggerFile) {
      continue;
    }

    const source = read(absolutePath);
    if (/from\s+["']evlog["']|require\(\s*["']evlog["']\s*\)/.test(source)) {
      violations.push(toRepoRelativePath(absolutePath));
    }
  }

  return violations;
};

const findConsoleUsage = () => {
  const files = globSync("src/**/*.{ts,tsx,mts,cts}", {
    cwd: repoRoot,
    absolute: true,
  });
  const violations = [];

  for (const file of files) {
    const absolutePath = toAbsolutePath(file);
    if (absolutePath === loggerFile) {
      continue;
    }

    const source = read(absolutePath);
    if (/\bconsole\.(debug|log|info|warn|error)\b/.test(source)) {
      violations.push(toRepoRelativePath(absolutePath));
    }
  }

  return violations;
};

const findUnwrappedApiRoutes = () => {
  const routes = globSync("src/app/api/**/route.ts", {
    cwd: repoRoot,
    absolute: true,
  });
  const violations = [];

  for (const route of routes) {
    const absolutePath = toAbsolutePath(route);
    const source = read(absolutePath);
    if (!source.includes("runWithApiRequestLog(")) {
      violations.push(toRepoRelativePath(absolutePath));
    }
  }

  return violations;
};

const findSensitiveLoggingKeys = () => {
  const files = globSync("src/**/*.{ts,tsx,mts,cts}", {
    cwd: repoRoot,
    absolute: true,
  });
  const violations = [];

  for (const file of files) {
    const absolutePath = toAbsolutePath(file);
    const source = read(absolutePath);

    for (const pattern of loggingObjectLiteralRegexes) {
      pattern.lastIndex = 0;
      let match = pattern.exec(source);
      while (match) {
        const objectText = match[0];
        if (sensitiveLogKeyRegex.test(objectText)) {
          violations.push(toRepoRelativePath(absolutePath));
          break;
        }
        match = pattern.exec(source);
      }
      if (violations[violations.length - 1] === toRepoRelativePath(absolutePath)) {
        break;
      }
    }
  }

  return violations;
};

const directEvlogImports = findDirectEvlogImports();
const consoleUsage = findConsoleUsage();
const unwrappedRoutes = findUnwrappedApiRoutes();
const sensitiveLoggingKeys = findSensitiveLoggingKeys();

fail("Direct evlog imports outside logger entrypoint", directEvlogImports);
fail("console.* usage outside logger entrypoint", consoleUsage);
fail("API routes missing runWithApiRequestLog wrapper", unwrappedRoutes);
fail("Sensitive keys found in logging payloads", sensitiveLoggingKeys);

if (
  directEvlogImports.length > 0 ||
  consoleUsage.length > 0 ||
  unwrappedRoutes.length > 0 ||
  sensitiveLoggingKeys.length > 0
) {
  process.exit(1);
}

console.log("[observability] conventions check passed");

