export const clearStagedChanges = async (runId: string): Promise<void> => {
  await db
    .delete(indexRunFileChanges)
    .where(eq(indexRunFileChanges.runId, runId))
}

export const stageUpsert = async (args: {
  runId: string
  path: string
  fileId: string
  sizeBytes: number
}) => {
  const now = new Date()
  await db
    .insert(indexRunFileChanges)
    .values({
      runId: args.runId,
      path: args.path,
      changeType: 'upsert',
      fileId: args.fileId,
      sizeBytes: args.sizeBytes,
      skipReason: null,
      createdAt: now,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: [indexRunFileChanges.runId, indexRunFileChanges.path],
      set: {
        changeType: 'upsert',
        fileId: args.fileId,
        sizeBytes: args.sizeBytes,
        skipReason: null,
        updatedAt: now,
      },
    })
}

export const stageDelete = async (args: {
  runId: string
  path: string
  skipReason?: string | null
}) => {
  const now = new Date()
  await db
    .insert(indexRunFileChanges)
    .values({
      runId: args.runId,
      path: args.path,
      changeType: 'delete',
      fileId: null,
      sizeBytes: null,
      skipReason: args.skipReason ?? null,
      createdAt: now,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: [indexRunFileChanges.runId, indexRunFileChanges.path],
      set: {
        changeType: 'delete',
        fileId: null,
        sizeBytes: null,
        skipReason: args.skipReason ?? null,
        updatedAt: now,
      },
    })
}

export const loadExistingStates = async (branchStateId: string): Promise<Map<string, ExistingFileState>> => {
  const rows = await db
    .select({
      path: indexFileStates.path,
      fileId: indexFileStates.fileId,
    })
    .from(indexFileStates)
    .where(eq(indexFileStates.branchStateId, branchStateId))

  return new Map(rows.map((row) => [row.path, row]))
}

import { NextResponse } from "next/server"

import { disconnectGitLabIntegration, getUserIntegration } from "@/lib/gitlab/service"
import { getSessionUserId } from "@/lib/session"
import { runWithApiRequestLog } from "@/lib/utils/logger"

export async function POST(
  request: Request,
  context: { params: Promise<{ integrationId: string }> },
) {
  const { integrationId } = await context.params
  return runWithApiRequestLog({
    request,
    path: `/api/gitlab/integrations/${integrationId}/disconnect`,
    event: "api.gitlab.integrations.disconnect",
    context: { integrationId },
    handler: async ({ logger }) => {
      const userId = await getSessionUserId()
      if (!userId) {
        return {
          status: 401,
          outcome: "unauthorized",
          response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
        }
      }

      const integration = await getUserIntegration(integrationId, userId)
      if (!integration) {
        return {
          status: 404,
          outcome: "not_found",
          response: NextResponse.json({ error: "Integration not found." }, { status: 404 }),
        }
      }

      const result = await disconnectGitLabIntegration({
        integration,
        userId,
      })
      logger.set({
        scope: result.scope,
      })
      return {
        status: 200,
        outcome: "success",
        response: NextResponse.json({
          data: {
            scope: result.scope,
          },
          warning: result.warning,
        }),
      }
    },
  })
}

